# Model 1 of the 3D matching coupled Poisson example (hexahedra):
# [0.0,0.5] x [0,1] x [0,1], 2 x 2 x 2 cubes, generated by cubemesh.
# Included by pdeapp.jl, which loads Exasim.
pde[1], mesh[1] = Exasim.initializeexasim();

pde[1].model = "ModelD";
pde[1].modelfile = "pdemodel1";    # module defined in pdemodel1.jl
include(joinpath(@__DIR__, "pdemodel1.jl"));
pde[1].modelnumber = 1;
pde[1].Cxxpreprocessing = 1;
pde[1].mpiprocs = 1;
pde[1].hybrid = 1;
pde[1].porder = 2;
pde[1].pgauss = 4;
pde[1].physicsparam = reshape([1.0], 1, 1);
pde[1].tau = [1.0];
pde[1].NLiter = 4;
pde[1].NLtol = 1e-12;
pde[1].linearsolvertol = 1e-12;
pde[1].matvectol = 1e-12;
pde[1].GMRESrestart = 250;
pde[1].linearsolveriter = 600;
pde[1].interfacetype = 0;

mesh[1].p, mesh[1].t = Exasim.Mesh.cubemesh(2, 2, 2, 1);
mesh[1].p[1, :] = 0.5 .* mesh[1].p[1, :];   # map x to [0,0.5]
# Boundaries: y = 0, x = 0.5, y = 1, x = 0, z = 0, z = 1
mesh[1].boundaryexpr = [p -> abs.(p[2,:]) .< 1e-8, p -> abs.(p[1,:] .- 0.5) .< 1e-8,
    p -> abs.(p[2,:] .- 1) .< 1e-8, p -> abs.(p[1,:]) .< 1e-8,
    p -> abs.(p[3,:]) .< 1e-8, p -> abs.(p[3,:] .- 1) .< 1e-8];
mesh[1].boundarycondition = [1 2 1 1 1 1];
mesh[1].interfacecondition = [0 1 0 0 0 0];   # boundary 2 is the coupled interface
pde[1].interfacefluxmap = [1];
